CREATE TYPE "MediaType" AS ENUM ('IMAGE','VIDEO'); CREATE TYPE "ProcessingStatus" AS ENUM ('UPLOADED','QUEUED','PROCESSING','READY','FAILED','QUARANTINED');
CREATE TYPE "ModerationStatus" AS ENUM ('PENDING','APPROVED','REJECTED'); CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "PortfolioFormat" AS ENUM ('SINGLE_IMAGE','ALBUM','SHORT_VIDEO','REEL'); CREATE TYPE "CopyrightReportStatus" AS ENUM ('OPEN','REVIEWING','RESOLVED','DISMISSED');
CREATE TABLE media_upload_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,object_path varchar(500) NOT NULL UNIQUE,media_type "MediaType" NOT NULL,mime_type varchar(100) NOT NULL,expected_size integer NOT NULL CHECK(expected_size>0),expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX media_upload_intents_business_expires_idx ON media_upload_intents(business_id,expires_at);
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES vendor_businesses(id) ON DELETE CASCADE,object_path varchar(500) NOT NULL UNIQUE,media_type "MediaType" NOT NULL,mime_type varchar(100) NOT NULL,byte_size integer NOT NULL CHECK(byte_size>0),width integer,height integer,duration_seconds integer,processing_status "ProcessingStatus" NOT NULL DEFAULT 'UPLOADED',moderation_status "ModerationStatus" NOT NULL DEFAULT 'PENDING',thumbnail_path varchar(500),processed_path varchar(500),failure_reason varchar(500),retry_count integer NOT NULL DEFAULT 0,rights_declared boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX media_assets_business_processing_moderation_idx ON media_assets(business_id,processing_status,moderation_status);
CREATE TABLE portfolio_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES vendor_businesses(id) ON DELETE CASCADE,category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,city_id uuid NOT NULL REFERENCES locations(id) ON DELETE RESTRICT,related_package_id uuid REFERENCES vendor_packages(id) ON DELETE SET NULL,format "PortfolioFormat" NOT NULL,caption varchar(2200),event_type varchar(80),tags text[] NOT NULL DEFAULT '{}',publication_status "PublicationStatus" NOT NULL DEFAULT 'DRAFT',published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX portfolio_posts_business_publication_published_idx ON portfolio_posts(business_id,publication_status,published_at);
CREATE TABLE portfolio_media(post_id uuid NOT NULL REFERENCES portfolio_posts(id) ON DELETE CASCADE,media_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,sort_order integer NOT NULL DEFAULT 0,is_cover boolean NOT NULL DEFAULT false,PRIMARY KEY(post_id,media_id));
CREATE UNIQUE INDEX portfolio_media_one_cover_idx ON portfolio_media(post_id) WHERE is_cover;
CREATE TABLE media_moderation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),media_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,actor_user_id uuid NOT NULL,decision "ModerationStatus" NOT NULL,reason varchar(1000),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX media_moderation_events_media_created_idx ON media_moderation_events(media_id,created_at);
CREATE TABLE copyright_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),media_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,reporter_email varchar(254) NOT NULL,statement varchar(3000) NOT NULL,status "CopyrightReportStatus" NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX copyright_reports_status_created_idx ON copyright_reports(status,created_at);
ALTER TABLE media_upload_intents ENABLE ROW LEVEL SECURITY; ALTER TABLE media_assets ENABLE ROW LEVEL SECURITY; ALTER TABLE portfolio_posts ENABLE ROW LEVEL SECURITY; ALTER TABLE portfolio_media ENABLE ROW LEVEL SECURITY; ALTER TABLE media_moderation_events ENABLE ROW LEVEL SECURITY; ALTER TABLE copyright_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON media_upload_intents,media_assets,portfolio_posts,portfolio_media,media_moderation_events,copyright_reports FROM anon,authenticated;
INSERT INTO permissions(code,description) VALUES ('media.moderate','Review portfolio media and copyright reports') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN ('MODERATOR','SUPER_ADMIN') AND p.code='media.moderate' ON CONFLICT DO NOTHING;
SELECT pgmq.create('media_processing');
